#!/usr/bin/env python3
"""Freeze each original no-op/uninitialized-storage counterexample proof task."""
import argparse,json
from pathlib import Path
from meter_read_itp_coq import ROOT,save,sha

def prepare(taskroot):
 group='zero';plan=json.loads((ROOT/'benchmark/programs/zero/evaluation-plan.json').read_text());report=ROOT/'benchmark/results/zero'/plan['run_id']/'results.json';data=json.loads(report.read_text());out=ROOT/'benchmark/results/zero/20261016-itp-per-execution';oldhelper=ROOT/'benchmark/results/read/20261015-itp-refutations/proofs/ReadCounterHeap.v';generic=oldhelper.read_text().split('Lemma cell_value_0')[0];header=generic.split('Definition st ')[0];tasks=[]
 context=''
 for name,start,end in [('CommonAssertion.v','Definition store_4byte (','Definition store_8byte ('),('CommonAssertion.v','Definition store_byte_noninit','Definition store_8byte_noninit'),('CommonAssertion.v','Definition store_int (','Definition store_int64 ('),('ConAssertion.v','Definition TokenSet_join','Theorem valid_state_join'),('ConAssertion.v','Definition mstore (','Theorem mstore_mstore_noninit')]:
  text=(ROOT/'runtime/qcip/SeparationLogic/SeparationLogic'/name).read_text();context+='\n'+name+':\n'+text[text.index(start):text.index(end)]
 mem=(ROOT/'runtime/qcip/SeparationLogic/SeparationLogic/Mem.v').read_text();context+='\nMem.v:\n'+mem[mem.index('Definition single_byte_mem'):mem.index('#[export] Instance mem_join_congr')]
 for row in data['runs']:
  for mode in ['off','on']:
   m=row['tespec_'+mode]
   if m['status']!='UNKNOWN':continue
   case=row['plan_case'];assert case['expected']=='FAIL' and case['oracle']['operation']=='noop';p=case['binds']['args']['p'];raw=ROOT/m['report'];j=json.loads(raw.read_text())['results'][0];goals=list(raw.parent.rglob('*_goal.v'));assert len(goals)==1;residual=[x.removeprefix('proof_of_') for x in j['residual_vcs']];assert set(residual)=={'zero_return_wit_1','zero_return_wit_1_split_goal_spatial'};idx=len(tasks);task=taskroot/f'execution-{idx:02d}'
   binding={'group':group,'execution_index':idx,'variant':row['variant'],'case':row['case'],'mode':mode,'expected':'FAIL','report':str(raw.relative_to(ROOT)),'report_sha256':sha(raw),'goal':str(goals[0].relative_to(ROOT)),'goal_sha256':sha(goals[0]),'binds':row['binds'],'binds_sha256':row['binds_sha256'],'qcp_source_sha256':row['qcp_source_sha256'],'residual_vcs':residual,'precondition_goal':'zero_precondition_wit_1','helper_provenance':str(oldhelper.relative_to(ROOT)),'helper_provenance_sha256':sha(oldhelper),'helper_derivation':'Only previously checked generic st/cell/join/byte facts before first input-specific refutation, plus a new unproved definition of four genuinely Noninit bytes at the selected location. All new proof work is model-filled in Candidate.v.'};tasks.append(binding)
   if (task/'binding.json').exists():assert json.loads((task/'binding.json').read_text())==binding;continue
   helper=generic+f'\nDefinition uninit_mem : mem := fun x => if Z.leb {p} x then (if Z.ltb x {p+4} then Noninit else Noperm) else Noperm.\n'
   facts=[('entry_cell',f'({p} # Int |->_) (st uninit_mem)'),('exit_cell',f'~ ({p} # Int |-> 0) (st uninit_mem)')]+[('refute_'+name,'~ ExecutionGoal.'+name) for name in residual]+[('entry_sat','ExecutionGoal.zero_precondition_wit_1')]
   candidate='Require Import ConcreteCell ExecutionGoal.\n'+header+'\n'+''.join(f'Theorem {name} : {statement}.\nProof. Admitted.\n' for name,statement in facts)+''.join(f'Print Assumptions {name}.\n' for name,_ in facts)
   task.mkdir(parents=True,exist_ok=True);save(task/'binding.json',binding);(task/'ExecutionGoal.v').write_bytes(goals[0].read_bytes());(task/'ConcreteCell.v').write_text(helper);(task/'Candidate.v').write_text(candidate);(task/'template.txt').write_text(candidate)
   prompt='Fill Candidate.v for this ONE finite no-op execution, proving BOTH original residual VC negations and original entry satisfiability. Exactly five Theorems and their statements/Print Assumptions must remain. You may add locally proved Lemmas in Candidate.v. Edit Candidate.v only; no models/delegation, prior benchmark proof solutions, shell/compiler calls, admits, new axioms or changed imported goals. All model attempts and compile/kernel costs are controller-metered. Coqc has 90-second/4-GiB caps; avoid firstorder on heap predicates.\nThe actual entry has genuinely uninitialized storage. uninit_mem has Noninit at all four owned bytes, not a coincidental initialized value. Prove entry_cell by assembling four single_Noninit_mem byte states through sepcon. Prove the negative exit_cell by destructing store_int/store_4byte: the first mstore requires a value byte at the base, whereas the whole heap has Noninit there; specializing its mem_join at the base gives a constructor contradiction. No byte merge arithmetic is needed for this contradiction. Then instantiate each original residual goal with the exact bound pointer and reflexivity, apply it to entry_cell, and contradict exit_cell. Prove entry_sat using the same concrete state witness. Runtime low-level join/set definitions are qualified ConAssertion.state_join, ConAssertion.TokenSet_join, ConAssertion.STS_state_join. Pointwise reasoning avoids functional extensionality; preserve all original VCs.\nGeneric utility and new heap DEFINITION (no prior input-specific proof):\n'+helper+'\nActual runtime declarations:\n'+context+'\nActual immutable finite goal:\n'+goals[0].read_text()+'\nExact candidate:\n'+candidate
   (task/'prompt.txt').write_bytes(prompt.encode('utf8'))
 save(out/'tasks.json',{'schema':'tespec-cell-leak-itp-tasks/v1','group':group,'proof_kind':'uninitialized_noop_wrong_post','evaluation_report':str(report.relative_to(ROOT)),'evaluation_report_sha256':sha(report),'tasks':tasks});print('Prepared',len(tasks),'independent zero no-op tasks',flush=True)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--task-root',type=Path,required=True);a=p.parse_args();prepare(a.task_root)
